    correction: [{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = -x + 1 + √5</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = -(<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - √5) + 1 + √5</span>"},{"quoi":"نزيل القوس","math":"<span dir=\"ltr\" class=\"expr\">E = 1 + √5 - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + √5</span>"},{"quoi":"نجمع الحدود المتشابهة","math":"نجمع الأعداد الناطقة مع بعضها و الأعداد الصمّاء مع بعضها"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + 2√5</span>"}],
