    correction: [{"quoi":"نترجم المعطى","math":"متساويان معناه <span dir=\"ltr\" class=\"expr\">E = -2 + √2</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-x + 1 + √5 = -2 + √2</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">-x = -2 + √2 - (1 + √5)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-2 + √2 - (1 + √5) = -3 + √2 - √5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 3 - √2 + √5</span>"}],
