    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">D = y + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> - y - y + √3 + 2 - √3 - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + 2y - <span class=\"frac\"><span class=\"num\">21</span><span class=\"den\">5</span></span> + √3</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">D = (y - y - y + 2y) + (<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> + 2 - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">21</span><span class=\"den\">5</span></span>) + (√3 - √3 + √3)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">D = y - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + √3</span>"}],
