    correction: [{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">x + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">5</span></span> - √2 = √3</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">5</span></span> + √2 + √3</span>"},{"quoi":"نحدّد الإشارة","math":"العدد <span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">5</span></span> + √2 + √3</span> هو عدد موجب تقريبا يساوي 0.55"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد موجب هي هو نفسه، و لعدد سالب هي مقابله"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">|x| = -<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">5</span></span> + √2 + √3</span>"}],
