    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">C = 1 + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + x + x + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + x - √2 - x - x - 11</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">C = (x + x + x - x - x) + (1 + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - 11) - √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">C = x - 6 - √2</span>"}],
