    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(x + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2) - [-x - (1 + 1 + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>)] + x - 2x - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - 2√2 = x + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - √2</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">x + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - √2 = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span></span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - (<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - (<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - √2) = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + √2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + √2</span>"}],
