    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">[1 + √5] + [1 - (-a + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span>)] + (1 + √5 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span>) - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">6</span></span> - 3√5 = a - 1 - √5</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">a - 1 - √5 = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + √5</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + √5 - (-1 - √5)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + √5 - (-1 - √5) = -<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> + 2√5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> + 2√5</span>"}],
