    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-π - [<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + (π - 7 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span>)] + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - x - <span class=\"frac\"><span class=\"num\">101</span><span class=\"den\">12</span></span> + π = -x - 3 - π</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">-x - 3 - π = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">-x = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - (-3 - π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - (-3 - π) = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - π</span>"}],
