    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = 4 - √2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> - √2 - √2 + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + 3 - √2 + 2a + b - <span class=\"frac\"><span class=\"num\">48</span><span class=\"den\">5</span></span> + 5√2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = 2a + b + (4 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + 3 - <span class=\"frac\"><span class=\"num\">48</span><span class=\"den\">5</span></span>) + (-√2 - √2 - √2 - √2 + 5√2)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 2a + b + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> + √2</span>"}],
