    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + 4 - π - 4 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> - π - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + 1 + π + a + 2b - <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">6</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a + 2b + (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + 4 - 4 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + 1 - <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">6</span></span>) + (-π - π + π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = a + 2b - 3 - π</span>"}],
