    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = -1 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - π + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - 4 - π + a + 3b + <span class=\"frac\"><span class=\"num\">59</span><span class=\"den\">4</span></span> + π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a + 3b + (-1 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - 4 + <span class=\"frac\"><span class=\"num\">59</span><span class=\"den\">4</span></span>) + (-π - π + π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = a + 3b + 7 - π</span>"}],
