    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = √5 + √5 + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + 1 + √5 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + √5 + a + 1 - 2a - <span class=\"frac\"><span class=\"num\">199</span><span class=\"den\">30</span></span> - 5√5</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (a - 2a) + (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + 1 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + 1 - <span class=\"frac\"><span class=\"num\">199</span><span class=\"den\">30</span></span>) + (√5 + √5 + √5 + √5 - 5√5)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = -a - 4 - √5</span>"}],
